// api/price.ts
import { httpInstance as http } from '../utils/http';
import type { ResType } from './shared';

export type PriceOption = {
    label: string;
    value: string; // 如 "0-150", "150-300"
};

type PriceRes = {
    priceOptions: PriceOption[];
};

export function fetchPriceStarOptions() {
    return http.request<ResType<PriceRes>>({
        url: '/price/options',
        method: 'GET',
    });
}
